using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Models;
using FoodParkDigital.Application.Common.Interfaces;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

namespace FoodParkDigital.Infrastructure.Services;

public class AzureBlobFileStorageService : IFileStorageService
{
    // URLs generated by LocalFileStorageService keep the same folder layout inside the container.
    private const string LegacyLocalUrlPrefix = "/uploads/";

    private static readonly string[] VariantSuffixes =
        ["_original", "_lg", "_md", "_sm", "_xs"];

    private readonly BlobContainerClient _containerClient;
    private readonly bool _autoCreateContainer;
    private readonly ILogger<AzureBlobFileStorageService> _logger;

    public AzureBlobFileStorageService(IConfiguration configuration, ILogger<AzureBlobFileStorageService> logger)
    {
        _logger = logger;

        var connectionString = configuration["FileStorage:AzureBlob:ConnectionString"];
        var containerName = configuration["FileStorage:AzureBlob:ContainerName"];

        if (string.IsNullOrWhiteSpace(connectionString))
            throw new InvalidOperationException("FileStorage:AzureBlob:ConnectionString no esta configurado.");

        if (string.IsNullOrWhiteSpace(containerName))
            throw new InvalidOperationException("FileStorage:AzureBlob:ContainerName no esta configurado.");

        _autoCreateContainer = configuration.GetValue<bool>("FileStorage:AzureBlob:AutoCreateContainer");

        var blobServiceClient = new BlobServiceClient(connectionString);
        _containerClient = blobServiceClient.GetBlobContainerClient(containerName);
    }

    public async Task<string> UploadAsync(
        Stream fileStream,
        string fileName,
        string contentType,
        string folder,
        CancellationToken cancellationToken = default)
    {
        if (_autoCreateContainer)
            await _containerClient.CreateIfNotExistsAsync(cancellationToken: cancellationToken);

        var safeFolder = folder.Trim('/').Replace("\\", "/");
        var blobName = $"{safeFolder}/{fileName}";
        var blobClient = _containerClient.GetBlobClient(blobName);

        await blobClient.UploadAsync(
            fileStream,
            new BlobUploadOptions
            {
                HttpHeaders = new BlobHttpHeaders
                {
                    ContentType = contentType,
                    // PDFs can carry scripts and links: they are downloaded instead of rendered.
                    ContentDisposition = contentType.Equals("application/pdf", StringComparison.OrdinalIgnoreCase)
                        ? "attachment"
                        : null
                }
            },
            cancellationToken);

        return blobClient.Uri.ToString();
    }

    public async Task DeleteAsync(string fileUrl, string folder, CancellationToken cancellationToken = default)
    {
        if (TryResolveBlobName(fileUrl, folder, out var blobName))
            await DeleteBlobAsync(blobName, cancellationToken);
    }

    public async Task DeleteVariantsAsync(string baseImageUrl, string folder, CancellationToken cancellationToken = default)
    {
        if (!TryResolveBlobName(baseImageUrl, folder, out var baseBlobName))
            return;

        // The suffixes contain no separators, so every variant stays next to the validated base name.
        foreach (var suffix in VariantSuffixes)
        {
            await DeleteBlobAsync($"{baseBlobName}{suffix}.webp", cancellationToken);
        }
    }

    private async Task DeleteBlobAsync(string blobName, CancellationToken cancellationToken)
    {
        var blobClient = _containerClient.GetBlobClient(blobName);
        await blobClient.DeleteIfExistsAsync(
            DeleteSnapshotsOption.IncludeSnapshots,
            cancellationToken: cancellationToken);
    }

    private bool TryResolveBlobName(string fileUrl, string folder, out string blobName)
    {
        if (TryResolveBlobName(_containerClient.Uri, fileUrl, folder, out blobName))
            return true;

        if (!string.IsNullOrWhiteSpace(fileUrl))
            _logger.LogWarning("Refused to delete a blob outside the storage folder {Folder}.", folder);

        return false;
    }

    // Maps a stored URL to a blob name of this container, only when the blob lies inside folder.
    // Accepts URLs of this container (same scheme, host, port and container path) and legacy local
    // "/uploads/..." URLs. Traversal and encoded separators are rejected, not normalized.
    internal static bool TryResolveBlobName(Uri containerUri, string fileUrl, string folder, out string blobName)
    {
        StorageNamespace.EnsureValidFolder(folder);
        blobName = string.Empty;

        if (string.IsNullOrWhiteSpace(fileUrl))
            return false;

        var containerPath = containerUri.AbsolutePath.TrimEnd('/') + "/";
        string relativePath;

        // Checked before Uri.TryCreate: on Unix "/uploads/..." parses as an absolute file:// URI.
        if (fileUrl.StartsWith(LegacyLocalUrlPrefix, StringComparison.Ordinal))
        {
            relativePath = fileUrl[LegacyLocalUrlPrefix.Length..];
        }
        else if (Uri.TryCreate(fileUrl, UriKind.Absolute, out var uri)
            && string.Equals(
                uri.GetLeftPart(UriPartial.Authority),
                containerUri.GetLeftPart(UriPartial.Authority),
                StringComparison.OrdinalIgnoreCase)
            && uri.AbsolutePath.StartsWith(containerPath, StringComparison.Ordinal))
        {
            relativePath = Uri.UnescapeDataString(uri.AbsolutePath[containerPath.Length..]);
        }
        else
        {
            return false;
        }

        if (!StorageNamespace.IsInsideFolder(relativePath, folder))
            return false;

        blobName = relativePath;
        return true;
    }
}
